    if len(heights) == 0:
        return 0

    # Initialize variables
    min_students = 0
    cur_height = heights[0]
    last_index = len(heights) - 1

    # Iterate through the students
    for i in range(1, len(heights)):
        # If the current height is greater than the previous height, decrease the minimum students
        if heights[i] > cur_height:
            min_students += 1
        # If the current height is equal to the previous height, we need to check the next student
        elif heights[i] == cur_height:
            continue
        # If the current height is less than the previous height, we need to check the previous student
        else:
            while i < last_index and heights[i] < heights[i + 1]:
                i += 1
            min_students += 1

    return min_students

